import { createSurfer } from "./surfer.js";
import { createOcean } from "./ocean.js";
const ocean = createOcean();
const surfer = createSurfer();
let min = Infinity, max = -Infinity;
for (let i = 0; i < 300; i++) {
  const t = i / 30;
  ocean.update(t);
  surfer.update(t);
  const y = surfer.root.position.y;
  min = Math.min(min, y); max = Math.max(max, y);
}
let meshes = 0, nonFinite = 0;
surfer.root.traverse((o) => {
  if (o.isMesh) {
    meshes++;
    for (const v of o.geometry.attributes.position.array) if (!Number.isFinite(v)) nonFinite++;
  }
});
console.log({ meshes, nonFinite, boardBobRange: [min.toFixed(3), max.toFixed(3)], pitchNow: surfer.root.rotation.z.toFixed(3), rollNow: surfer.root.rotation.x.toFixed(3) });
